import java.io.*;
import java.util.*;

public class OneBasedArithmetic {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        long target = Long.parseLong(in.readLine());
        long[] repUnits = new long[17];
        for (int k = 1; k < 17; k++) {
            repUnits[k] = repUnits[k-1] * 10 + 1;
        }
        long answer = process(repUnits, target, 16);
        System.out.println(answer);
    }

    private static long process(long[] units, long remaining, int depth) {
        long unitValue = units[depth];
        long count = remaining / unitValue;
        long residue = remaining % unitValue;
        long cost = count * depth;
        if (residue == 0) {
            return cost;
        }
        long cost1 = cost + process(units, residue, depth - 1);
        long cost2 = cost + depth + process(units, unitValue - residue, depth - 1);
        return Math.min(cost1, cost2);
    }

    private static class FastReader {
        private final BufferedReader reader;
        private Iterator<String> tokenizer;

        public FastReader() {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = Collections.emptyIterator();
        }

        private String advance() throws IOException {
            while (!tokenizer.hasNext()) {
                tokenizer = Arrays.asList(reader.readLine().split("\\s+")).iterator();
            }
            return tokenizer.next();
        }

        public String next() {
            try {
                return advance();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public double nextDouble() {
            return Double.parseDouble(next());
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        }
    }
}
